{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "weaken",
  "supportive_card_ids": ["C05", "C24", "C08", "C14", "C01"],
  "contradictory_card_ids": ["C17", "C56", "C57", "C61", "C65"],
  "prediction_basis_card_ids": ["C05", "C24", "C08", "C14"],
  "claims": [
    {
      "claim": "KNI-272, the closest fed-state peptidomimetic context, had absolute oral bioavailability of 36.4% after a 6.6 mg/kg post-prandial capsule (n=2) and 22.06 ± 2.99% after a 4 mg/kg post-prandial capsule (n=5), both at or above the 20% threshold; the below-threshold 15.72 ± 5.96% value came from a 2 mg/kg cherry syrup, indicating dose/formulation dependence rather than a uniform low F.",
      "card_ids": ["C05", "C24", "C17"]
    },
    {
      "claim": "Atazanavir, a fed-state peptidomimetic HIV protease inhibitor with tert-butyl and hydroxyethyl motifs, has oral bioavailability >90% when taken with food; the L2 note of variability with food and gastrointestinal pH does not contradict the fed-state high value.",
      "card_ids": ["C08", "C14", "C18"]
    },
    {
      "claim": "L5 gut-wall records show that saquinavir is a P-gp substrate whose intestinal absorption is limited by efflux and that indinavir has low ileal permeability comparable to mannitol; these are mechanism-level observations for related molecules, not direct F measurements for the query, and do not affirmatively establish F < 20%.",
      "card_ids": ["C56", "C57", "C61", "C65"]
    },
    {
      "claim": "Low-F contexts (argatroban, danavorexton, rifampin-induced propafenone) are not structurally or conditionally transferable to the fed-state query, and physicochemical liabilities alone are not affirmative evidence for F < 20%.",
      "card_ids": ["C03", "C07", "C10"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64", "C65"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "Query dose and formulation are unspecified; KNI-272 fed F ranges from 15.72% (2 mg/kg syrup) to 36.4% (6.6 mg/kg capsule), so threshold classification could depend on formulation/dose.",
    "L5 gut-wall efflux and intestinal-metabolism records are for saquinavir and indinavir, not the query; no query-specific P-gp or intestinal metabolism data are available.",
    "No query-specific solubility or permeability data are available.",
    "Atazanavir bioavailability report type is unspecified, and the KNI-272 36.4% value is based on n=2."
  ],
  "decision_summary": "High, moderate confidence: the most transferable fed-state peptidomimetic evidence (KNI-272 post-prandial capsule F 22–36%; atazanavir >90% with food) supports F ≥ 20%; L5 gut-wall efflux records for saquinavir/indinavir introduce a plausible presystemic-loss mechanism but are indirect and do not overturn the fed-state direct F evidence; the below-threshold KNI-272 syrup value reflects dose/formulation dependence, and low-F contexts are not transferable."
}

